T = {
'card66_opt1_res0': ("A huge network of 65,000 addresses… and lots of useless traffic.\n\nDid you know? Networks that are too big are slower and less secure.", "Una red enorme de 65 000 direcciones… y mucho tráfico inútil.\n\n¿Lo sabías? Las redes demasiado grandes son más lentas y menos seguras."),
'card66_opt1': ("Switch to a /16 to be safe", "Pasar a /16 para estar tranquilo"),
'card66_text': ("The 192.168.1.0/24 network is saturated. The boss asks for subnets per department.", "La red 192.168.1.0/24 está saturada. El jefe pide crear subredes por departamento."),
'card66_title': ("Splitting the Network", "Dividir la red"),
'card67_opt0_res0': ("After a Proxmox prototype, the choice is clear and well argued.\n\nDid you know? Virtualization runs several virtual servers on a single physical machine.", "Tras una maqueta en Proxmox, la elección es clara y está bien argumentada.\n\n¿Lo sabías? La virtualización permite ejecutar varios servidores virtuales en una sola máquina física."),
'card67_opt0': ("Compare solutions and build a prototype", "Comparar soluciones y hacer una maqueta"),
'card67_opt1_res0': ("The chosen solution doesn't handle the required backups. Everything has to be redone.\n\nDid you know? A prototype (a small-scale test) avoids nasty surprises.", "La solución elegida no gestiona las copias de seguridad necesarias. Hay que rehacerlo todo.\n\n¿Lo sabías? Una maqueta (una prueba a pequeña escala) evita malas sorpresas."),
'card67_opt1': ("Take the first one you find", "Elegir la primera que aparezca"),
'card67_text': ("Ten old servers need to be virtualized. The boss asks for your opinion.", "Hay que virtualizar 10 servidores viejos. El jefe pide tu opinión."),
'card67_title': ("Which Hypervisor?", "¿Qué hipervisor?"),
'card68_opt0_res0': ("The host was out of RAM: {0.SimFirstName} rebalances the virtual machines.\n\nDid you know? If you give VMs more RAM than really exists, everything slows down.", "El anfitrión se había quedado sin RAM: {0.SimFirstName} reequilibra las máquinas virtuales.\n\n¿Lo sabías? Si se asigna a las VM más RAM de la que hay de verdad, todo se ralentiza."),
'card68_opt0': ("Check the host's resources", "Mirar los recursos del anfitrión"),
'card68_opt1_res0': ("It gets worse: the host was already overloaded.\n\nDid you know? Check the host (the physical machine) before the VM.", "Empeora: el anfitrión ya estaba saturado.\n\n¿Lo sabías? Se revisa el anfitrión (la máquina física) antes que la VM."),
'card68_opt1': ("Add RAM to the VM", "Añadir RAM a la VM"),
'card68_text': ("A virtual server is crawling: users wait 30 seconds on every click.", "Un servidor virtual va lentísimo: los usuarios esperan 30 segundos en cada clic."),
'card68_title': ("The VM Is Slow", "La VM va lenta"),
'card69_opt0_res0': ("Disk replaced, the RAID rebuilds. The backups are saved!\n\nDid you know? A disk that \"clicks\" is often about to fail.", "Disco cambiado, el RAID se reconstruye. ¡Las copias de seguridad se salvan!\n\n¿Lo sabías? Un disco que hace «clic» suele estar a punto de fallar."),
'card69_opt0_res1': ("{0.SimFirstName} pulls out the wrong disk… luckily the RAID holds.\n\nDid you know? You identify the failing disk by its bay number in the interface.", "{0.SimFirstName} saca el disco equivocado… por suerte el RAID aguanta.\n\n¿Lo sabías? El disco defectuoso se identifica por su número de bahía en la interfaz."),
'card69_opt0': ("Replace the disk right away", "Cambiar el disco de inmediato"),
'card69_opt1_res0': ("Two disks fail: all the backups are lost.\n\nDid you know? RAID 5 survives the failure of one disk, not two.", "Fallan dos discos: se pierden todas las copias de seguridad.\n\n¿Lo sabías? Un RAID 5 aguanta la avería de un solo disco, no de dos."),
'card69_opt1': ("Wait until the end of the month", "Esperar a final de mes"),
'card69_text': ("The backup NAS is making worrying \"click click\" sounds.", "El NAS de las copias hace unos «clic clic» preocupantes."),
'card69_title': ("The NAS Is Making Noise", "El NAS hace ruido"),
'card70_opt0_res0': ("The switch couldn't power that many cameras. {0.SimFirstName} spreads out the connections.\n\nDid you know? PoE (Power over Ethernet) powers a device through the network cable, but total power is limited.", "El switch no podía alimentar tantas cámaras. {0.SimFirstName} reparte las conexiones.\n\n¿Lo sabías? El PoE (Power over Ethernet) alimenta un aparato por el cable de red, pero la potencia total es limitada."),
'card70_opt0': ("Check the switch's PoE budget", "Revisar el presupuesto PoE del switch"),
'card70_opt1_res0': ("The new cameras have the same problem…\n\nDid you know? Before blaming the hardware, check compatibility.", "Las cámaras nuevas tienen el mismo problema…\n\n¿Lo sabías? Antes de culpar al hardware, se comprueba la compatibilidad."),
'card70_opt1': ("Send the cameras back", "Devolver las cámaras"),
'card70_text': ("The new security cameras don't turn on once plugged into the switch.", "Las nuevas cámaras de seguridad no se encienden al conectarlas al switch."),
'card70_title': ("The Cameras Won't Turn On", "Las cámaras no se encienden"),
'card71_opt0_res0': ("Visitors have their Wi-Fi, and the internal network is protected.\n\nDid you know? Internal Wi-Fi can use per-account authentication (WPA2-Enterprise) instead of a shared key.", "Los visitantes tienen su Wi-Fi y la red interna está protegida.\n\n¿Lo sabías? El Wi-Fi interno puede usar autenticación por cuenta (WPA2-Enterprise) en lugar de una clave compartida."),
'card71_opt0': ("Create a guest Wi-Fi and change the key", "Crear un Wi-Fi de invitados y cambiar la clave"),
'card71_opt1_res0': ("Too late, the password has been photographed. The network stays exposed.\n\nDid you know? A leaked key must be changed.", "Demasiado tarde, alguien ha fotografiado la contraseña. La red sigue expuesta.\n\n¿Lo sabías? Una clave filtrada hay que cambiarla."),
'card71_opt1': ("Take the poster down, that's enough", "Quitar el cartel, con eso basta"),
'card71_text': ("The internal Wi-Fi password is on a poster in the reception hall.", "La contraseña del Wi-Fi interno está en un cartel en el vestíbulo."),
'card71_title': ("The Wi-Fi Password on the Wall", "La contraseña Wi-Fi en la pared"),
'card72_opt0_res0': ("Everything is compliant thanks to the inventory. Audit passed with no fine.\n\nDid you know? Using unlicensed software can cost a company a lot.", "Todo en regla gracias al inventario. Auditoría superada sin multa.\n\n¿Lo sabías? Usar software sin licencia puede salirle muy caro a una empresa."),
'card72_opt0': ("Take inventory of the licenses", "Hacer el inventario de licencias"),
'card72_opt1_res0': ("30 licenses are missing: a big bill for the company.\n\nDid you know? There's also free software (like LibreOffice) with no license cost.", "Faltan 30 licencias: factura enorme para la empresa.\n\n¿Lo sabías? También existe software libre (como LibreOffice) sin coste de licencia."),
'card72_opt1': ("Cross your fingers", "Cruzar los dedos"),
'card72_text': ("A software vendor announces a license audit in a month.", "El editor de un programa anuncia una auditoría de licencias dentro de un mes."),
'card72_title': ("License Audit", "Auditoría de licencias"),
'card73_opt0_res0': ("A bash script and a cron job: the backup runs every night at 2 AM.\n\nDid you know? Cron is Linux's task scheduler (like Windows Task Scheduler).", "Un script bash y una tarea cron: la copia se ejecuta cada noche a las 2:00.\n\n¿Lo sabías? Cron es el programador de tareas de Linux (como el Programador de tareas de Windows)."),
'card73_opt0_res1': ("The script works, but {0.SimFirstName} forgot to check that it actually runs.\n\nDid you know? A scheduled script should send a report (email, log) so you know it succeeded.", "El script funciona, pero {0.SimFirstName} olvidó comprobar que se ejecuta de verdad.\n\n¿Lo sabías? Un script programado debe enviar un informe (correo, log) para saber si ha funcionado."),
'card73_opt0': ("Write a script and schedule it", "Escribir un script y programarlo"),
'card73_opt1_res0': ("The reminder is ignored during the holidays. Three weeks without a backup!\n\nDid you know? Anything that depends on human memory ends up forgotten.", "El recordatorio se ignora durante las vacaciones. ¡Tres semanas sin copia!\n\n¿Lo sabías? Lo que depende de la memoria humana acaba olvidándose."),
'card73_opt1': ("Put a reminder in the calendar", "Poner un recordatorio en la agenda"),
'card73_text': ("The Linux server backups are started by hand… whenever someone remembers.", "Las copias del servidor Linux se lanzan a mano… cuando alguien se acuerda."),
'card73_title': ("The Backup Script", "El script de copia de seguridad"),
'card74_opt0_res0': ("The printer always keeps the same address. Problem solved!\n\nDid you know? A DHCP reservation always gives a device the same IP, based on its MAC address.", "La impresora mantiene siempre la misma dirección. ¡Se acabó el problema!\n\n¿Lo sabías? Una reserva DHCP da siempre la misma IP a un aparato, gracias a su dirección MAC."),
'card74_opt0': ("Give it a DHCP reservation", "Darle una reserva DHCP"),
'card74_opt1_res0': ("It changes address the following week: back to square one.\n\nDid you know? The MAC address identifies the network card; the IP address can change.", "Cambia de dirección la semana siguiente: vuelta a empezar.\n\n¿Lo sabías? La dirección MAC identifica la tarjeta de red; la dirección IP puede cambiar."),
'card74_opt1': ("Reinstall the printer on every PC", "Reinstalar la impresora en cada equipo"),
'card74_text': ("Nobody can find the printer since the department moved.", "Nadie encuentra la impresora desde la mudanza del departamento."),
'card74_title': ("The Missing Network Printer", "La impresora de red desaparecida"),
'card75_opt0_res0': ("One department at a time, with tests: migration done with no lost emails.\n\nDid you know? DNS MX records say which server receives email for a domain.", "Un departamento cada vez, con pruebas: migración lograda sin perder correos.\n\n¿Lo sabías? Los registros DNS MX indican qué servidor recibe el correo de un dominio."),
'card75_opt0_res1': ("A few mailboxes get lost along the way and have to be recovered.\n\nDid you know? Keep the old server running for a few weeks after a migration.", "Algunos buzones se pierden por el camino y hay que recuperarlos.\n\n¿Lo sabías? Se deja el servidor antiguo encendido unas semanas después de una migración."),
'card75_opt0': ("Prepare a step-by-step migration", "Preparar una migración por etapas"),
'card75_opt1_res0': ("On Monday, half the emails stop arriving…\n\nDid you know? DNS changes take time to propagate (TTL).", "El lunes, la mitad de los correos ya no llegan…\n\n¿Lo sabías? Los cambios de DNS tardan en propagarse (TTL)."),
'card75_opt1': ("Switch everything over in one weekend", "Pasarlo todo en un fin de semana"),
'card75_text': ("Management wants to move email to the cloud (Microsoft 365).", "La dirección quiere pasar el correo a la nube (Microsoft 365)."),
'card75_title': ("Migrating the Mail Server", "Migrar el servidor de correo"),
'card76_opt0_res0': ("The offline backups weren't touched: everything is restored without paying!\n\nDid you know? Disconnected (or immutable) backups resist ransomware.", "Las copias desconectadas no se han tocado: ¡todo restaurado sin pagar!\n\n¿Lo sabías? Las copias desconectadas (o inmutables) resisten al ransomware."),
'card76_opt0_res1': ("The restore takes 3 days, but nothing is paid.\n\nDid you know? You file a police report and alert the national cybersecurity authorities.", "La restauración tarda 3 días, pero no se paga nada.\n\n¿Lo sabías? Se pone una denuncia y se avisa a las autoridades (en España, el INCIBE: línea 017)."),
'card76_opt0': ("Restore from the offline backups", "Restaurar desde las copias desconectadas"),
'card76_opt1_res0': ("The ransom is paid… and the hackers don't hand over the key.\n\nDid you know? Paying guarantees nothing and funds criminals. Authorities advise against paying.", "Se paga el rescate… y los atacantes no dan la clave.\n\n¿Lo sabías? Pagar no garantiza nada y financia a los delincuentes. Las autoridades desaconsejan pagar."),
'card76_opt1': ("Advise paying", "Aconsejar que se pague"),
'card76_text': ("Ransomware has encrypted a server. The hackers demand §50,000 in cryptocurrency.", "Un ransomware ha cifrado un servidor. Los atacantes piden 50 000 § en criptomoneda."),
'card76_title': ("The Ransom", "El rescate"),
'card77_opt0_res0': ("{0.SimFirstName} applies the workaround in 2 hours, then the patch as soon as it comes out.\n\nDid you know? A zero-day flaw is known to hackers before the vendor has released a fix.", "{0.SimFirstName} aplica la medida temporal en 2 horas y luego el parche en cuanto sale.\n\n¿Lo sabías? Un fallo de día cero (zero-day) lo conocen los atacantes antes de que el editor publique una corrección."),
'card77_opt0_res1': ("A few servers were forgotten in the rush.\n\nDid you know? An up-to-date inventory tells you which servers are affected.", "Con las prisas, se han olvidado algunos servidores.\n\n¿Lo sabías? Un inventario al día permite saber qué servidores están afectados."),
'card77_opt0': ("Apply the emergency measures", "Aplicar las medidas de urgencia"),
'card77_opt1_res0': ("Hackers exploit the flaw while you wait…\n\nDid you know? Government CERTs publish alerts and advice for serious flaws.", "Los atacantes explotan el fallo mientras se espera…\n\n¿Lo sabías? Los CERT (en España, el INCIBE-CERT) publican alertas y consejos sobre los fallos graves."),
'card77_opt1': ("Wait for the official patch", "Esperar el parche oficial"),
'card77_text': ("A critical \"zero-day\" flaw affects software used on every server.", "Un fallo crítico de día cero afecta a un programa usado en todos los servidores."),
'card77_title': ("Critical Flaw Announced", "Fallo crítico anunciado"),
'card78_opt0_res0': ("The malicious traffic is filtered, the site comes back.\n\nDid you know? A DDoS attack floods a server with thousands of requests from hacked machines.", "El tráfico malicioso se filtra y la web vuelve.\n\n¿Lo sabías? Un ataque DDoS ahoga un servidor con miles de peticiones desde máquinas hackeadas."),
'card78_opt0': ("Turn on DDoS protection", "Activar la protección anti-DDoS"),
'card78_opt1_res0': ("It goes down again immediately: the attack continues.\n\nDid you know? Against a DDoS, you filter traffic upstream, often with the hosting provider's help.", "Se cae enseguida: el ataque continúa.\n\n¿Lo sabías? Contra un DDoS, el tráfico se filtra antes de llegar, a menudo con ayuda del proveedor de alojamiento."),
'card78_opt1': ("Restart the web server", "Reiniciar el servidor web"),
'card78_text': ("The company website is getting millions of requests per second: it's no longer responding.", "La web de la empresa recibe millones de peticiones por segundo: ya no responde."),
'card78_title': ("The Site Is Overloaded", "La web está saturada"),
'card79_opt0_res0': ("Attackers are banned automatically, and the password is no longer used.\n\nDid you know? SSH key authentication is much safer than a password.", "Los atacantes quedan bloqueados automáticamente y ya no se usa la contraseña.\n\n¿Lo sabías? La autenticación con clave SSH es mucho más segura que una contraseña."),
'card79_opt0_res1': ("fail2ban also blocks… {0.SimFirstName}'s own address.\n\nDid you know? Add your own addresses to the allowlist before turning on blocking.", "fail2ban también bloquea… la dirección de {0.SimFirstName}.\n\n¿Lo sabías? Se añaden las propias direcciones a la lista blanca antes de activar un bloqueo."),
'card79_opt0': ("Block with fail2ban and SSH keys", "Bloquear con fail2ban y claves SSH"),
'card79_opt1_res0': ("A weak password eventually gets found. The server is compromised.\n\nDid you know? A brute-force attack tries thousands of passwords until it finds the right one.", "Una contraseña débil acaba encontrándose. El servidor está comprometido.\n\n¿Lo sabías? Un ataque de fuerza bruta prueba miles de contraseñas hasta dar con la buena."),
'card79_opt1': ("Ignore it, it's just noise", "Ignorarlo, es ruido"),
'card79_text': ("The logs show thousands of SSH login attempts on a server, from all over the world.", "Los registros muestran miles de intentos de conexión SSH a un servidor, desde todo el mundo."),
'card79_title': ("Thousands of SSH Logins", "Miles de conexiones SSH"),
'card80_opt0_res0': ("Users adopt KeePass. No more sticky notes!\n\nDid you know? A password manager remembers strong, different passwords for every site.", "Los usuarios adoptan KeePass. ¡Se acabaron los pósits!\n\n¿Lo sabías? Un gestor de contraseñas recuerda contraseñas fuertes y distintas para cada web."),
'card80_opt0': ("Suggest a password manager", "Proponer un gestor de contraseñas"),
'card80_opt1_res0': ("The next day, the sticky notes are back… under the keyboards.\n\nDid you know? Without an explanation, users don't change their habits.", "Al día siguiente, los pósits han vuelto… debajo de los teclados.\n\n¿Lo sabías? Sin explicaciones, los usuarios no cambian sus hábitos."),
'card80_opt1': ("Rip off the notes without a word", "Arrancar los pósits sin decir nada"),
'card80_text': ("Walking through the offices, {0.SimFirstName} sees passwords on sticky notes stuck to screens.", "Al pasar por las oficinas, {0.SimFirstName} ve contraseñas en pósits pegados a las pantallas."),
'card80_title': ("The Sticky Note on the Screen", "El pósit en la pantalla"),
'card81_opt0_res0': ("It was a hacker who had his password! The account is secured in time.\n\nDid you know? This attack is called \"MFA bombing\": the victim is flooded with prompts until they give in and accept.", "¡Era un atacante que tenía su contraseña! La cuenta se protege a tiempo.\n\n¿Lo sabías? Este ataque se llama «MFA bombing»: se inunda a la víctima de notificaciones hasta que acaba aceptando."),
'card81_opt0': ("Tell him to deny and lock his account", "Decirle que rechace y bloquear su cuenta"),
'card81_opt1_res0': ("The hacker gets into the mailbox…\n\nDid you know? Never approve a login request you didn't make yourself.", "El atacante entra en el correo…\n\n¿Lo sabías? Nunca se aprueba una solicitud de conexión que no ha hecho uno mismo."),
'card81_opt1': ("Tell him to accept for some peace", "Decirle que acepte para tener paz"),
'card81_text': ("A user receives 50 two-factor approval requests on his phone. He's tempted to accept just to make it stop.", "Un usuario recibe 50 solicitudes de validación de doble autenticación en su móvil. Tiene la tentación de aceptar para que pare."),
'card81_title': ("Notification Barrage", "Notificaciones en ráfaga"),
'card82_opt0_res0': ("Passwords changed within 1 hour: the list is now worthless.\n\nDid you know? The site haveibeenpwned.com lets you check whether your email address has leaked.", "Contraseñas cambiadas en 1 hora: la lista ya no vale nada.\n\n¿Lo sabías? La web haveibeenpwned.com permite comprobar si tu correo se ha filtrado."),
'card82_opt0': ("Force a reset of the affected passwords", "Forzar el cambio de las contraseñas afectadas"),
'card82_opt1_res0': ("It was real… and one account has already been used.\n\nDid you know? When in doubt, act fast: changing a password costs almost nothing.", "Era verdad… y una cuenta ya se ha usado.\n\n¿Lo sabías? Ante la duda, se actúa rápido: cambiar una contraseña no cuesta casi nada."),
'card82_opt1_res1': ("It was an old, outdated list. False alarm.\n\nDid you know? Checking is good, but not for too long.", "Era una lista antigua y caducada. Falsa alarma.\n\n¿Lo sabías? Comprobar está bien, pero sin tardar demasiado."),
'card82_opt1': ("First check whether it's true", "Comprobar primero si es verdad"),
}
